	/** A declined projection remains declined for the whole resumable activation, even if memory becomes available. */
	@ParameterizedTest(name = "compiled={0}")
	@ValueSource(booleans = { false, true })
	void declinedProjectionChoiceStaysFallbackAcrossAvailabilityChange(boolean compiled) throws Exception {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1_000_000L, 1_000_000L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			LmdbQueryMemoryManager.Reservation blocker = ledger.reserve(manager.maxBytes() - 1L, null);
			assertNotNull(blocker, "the blocker must make the first projection admission fail");
			Adjacency source = new Adjacency(new long[] { 10 }, new long[][] { { 100 } }, new long[][] { { 1 } });
			Kernel ir = new Kernel(5, programs(), new Emit(new int[] { 0, 1, 2, 3, 4 }, false, OutputMods.none()));
			JaninoKernel execution = compiled ? KernelCompilationTestSupport.compile(ir)
					: LmdbNativeKernelInterpreter.forRows(ir);
			assertNotNull(execution);
			try {
				execution.bind(new KernelContext(new NativeAdjacency[] { source }, new long[] { 10 }, new long[0],
						new long[0][], new CountingHooks()).withMemoryLedger(ledger));
				long[] buffer = new long[ir.stride()];
				assertEquals(1, execution.fill(buffer, 1));
				blocker.close();
				assertEquals(0, execution.fill(buffer, 1),
						"a resumable fallback must not restart a projection after admission changes");
			} finally {
				execution.close();
			}
		}
	}

	@Test
	void vectorTailSelectionPreservesEarlierAndReusableProjectionWork() {
		String previous = System.getProperty(LmdbNativeKernelIr.VECTOR_TAIL_PROPERTY);
		System.setProperty(LmdbNativeKernelIr.VECTOR_TAIL_PROPERTY, "true");
		try {
			Kernel denseId = new Kernel(2,
					List.of(new EnumerateAdjKeys(0, 0, 1),
							new FilterCompareId(false, Operand.col(1), Operand.constant(0))),
					emit(0, 1));
			assertEquals(0, denseId.vectorTailIndex, "a dense ID filter keeps the vector tail");
			assertTrue(denseId.producerSchedules.isEmpty(), "the selected vector tail removes its projection schedule");

			FilterValue rootScalar = new FilterValue(1, new Operand[] { Operand.col(0) }, true);
			Kernel rootScalarKernel = new Kernel(2, List.of(new EnumerateAdjKeys(0, 0, 1), rootScalar), emit(0, 1));
			assertEquals(-1, rootScalarKernel.vectorTailIndex, "root-dependent scalar work stays in the projection");
			LmdbNativeProducerSchedule rootScalarSchedule = rootScalarKernel.producerSchedules
					.forNode(rootScalarKernel.pipeline.get(0));
			assertNotNull(rootScalarSchedule);
			assertTrue(rootScalarSchedule.programs.get(LmdbNativeProducerSchedule.ROOT).contains(rootScalar));

			FilterValue pageProof = new FilterValue(2, new Operand[] { Operand.col(0) }, true,
					KernelTermKindProof.forKind(0, 1 << ValueIds.TERM_KIND_LITERAL));
			Kernel pageProofKernel = new Kernel(2, List.of(new EnumerateAdjKeys(0, 0, 1), pageProof), emit(0, 1));
			assertEquals(-1, pageProofKernel.vectorTailIndex,
					"page-proof work remains available before payload decoding");
			LmdbNativeProducerSchedule pageProofSchedule = pageProofKernel.producerSchedules
					.forNode(pageProofKernel.pipeline.get(0));
			assertNotNull(pageProofSchedule);
			assertTrue(pageProofSchedule.programs.get(LmdbNativeProducerSchedule.ROOT).contains(pageProof));

			FilterValue fiberComputed = new FilterValue(3, new Operand[] { Operand.col(1) }, true);
			Kernel fiberComputedKernel = new Kernel(2,
					List.of(new EnumerateAdjKeys(0, 0, 1), fiberComputed), emit(0, 1));
			assertEquals(-1, fiberComputedKernel.vectorTailIndex,
					"reusable fiber computation stays once per object rather than repeating per graph row");
			LmdbNativeProducerSchedule fiberSchedule = fiberComputedKernel.producerSchedules
					.forNode(fiberComputedKernel.pipeline.get(0));
			assertNotNull(fiberSchedule);
			assertTrue(fiberSchedule.programs.get(LmdbNativeProducerSchedule.FIBER).contains(fiberComputed));

			Kernel weightedNumeric = new Kernel(2, List.of(new EnumerateAdjKeys(0, 0, 1)),
					new Aggregate(new int[] { 0 }, new AggregateOutput[] { AggregateOutput.sum(1) }, null,
							OutputMods.none()));
			assertEquals(-1, weightedNumeric.vectorTailIndex,
					"weighted numeric aggregation retains its projection schedule");
			LmdbNativeProducerSchedule weightedSchedule = weightedNumeric.producerSchedules
					.forNode(weightedNumeric.pipeline.get(0));
			assertNotNull(weightedSchedule);
			assertTrue(weightedSchedule.weightedNumeric);
		} finally {
			if (previous == null) {
				System.clearProperty(LmdbNativeKernelIr.VECTOR_TAIL_PROPERTY);
			} else {
				System.setProperty(LmdbNativeKernelIr.VECTOR_TAIL_PROPERTY, previous);
			}
		}
	}

	private static List<Node> programs() {
		return List.of(new EnumerateAdjKeys(0, 0, 1, 2, null, true),
				new BindHook(0, new Operand[] { Operand.col(0) }, 3, false),
				new BindHook(1, new Operand[] { Operand.col(1) }, 4, false));
	}

	private static Emit emit(int... columns) {
		return new Emit(columns, false, OutputMods.none());
	}

	private static Adjacency fixture() {
		return new Adjacency(new long[] { 10, 20 }, new long[][] { { 100, 100, 101 }, { 200, 200 } },
				new long[][] { { 0, 1, 2 }, { 3, 4 } });
	}

	private static long distinctKey(int aggregateId, int groupId) {
		return ((long) aggregateId << 32) | Integer.toUnsignedLong(groupId);
	}

	private static List<String> run(Kernel ir, NativeAdjacency source, CountingHooks hooks, boolean compiled)
			throws Exception {
		return run(ir, new NativeAdjacency[] { source }, hooks, compiled);
	}

	private static List<String> run(Kernel ir, NativeAdjacency[] sources, CountingHooks hooks, boolean compiled)
			throws Exception {
		JaninoKernel execution = compiled ? KernelCompilationTestSupport.compile(ir)
				: ir.terminal instanceof Aggregate ? LmdbNativeKernelInterpreter.forAggregate(ir)
						: LmdbNativeKernelInterpreter.forRows(ir);
		assertNotNull(execution);
		try {
			execution.bind(new KernelContext(sources, new long[] { 10 }, new long[0], new long[0][], hooks));
			List<String> rows = new ArrayList<>();
			long[] buffer = new long[ir.stride()];
			while (execution.fill(buffer, 1) > 0) {
				rows.add(Arrays.toString(buffer));
				assertTrue(rows.size() < 100, "cursor did not advance across a single-row pause");
			}
			return rows;
		} finally {
			execution.close();
		}
	}

	private static final class CountingHooks implements KernelHooks {
		int rootCalls;
		int fiberCalls;
		final Map<Long, Set<Long>> distinctValues = new HashMap<>();

		@Override
		public boolean testFilter(int filterId, long a, long b, long c) {
			throw new AssertionError("fixture uses only ID guards");
		}

		@Override
		public long computeBind(int bindId, long left, long right) {
			if (bindId == 0) {
				rootCalls++;
				return left + 1000L;
			}
			fiberCalls++;
			return left + 2000L;
		}

		@Override
		public int compareValues(long left, long right) {
			return Long.compare(left, right);
		}

		@Override
		public boolean isNumeric(long id) {
			return true;
		}

		@Override
		public double doubleValue(long id) {
			return id;
		}

		@Override
		public void accumulateNumeric(int aggregateId, int groupId, long valueId) {
			throw new AssertionError("fixture uses counts and extrema");
		}

		@Override
		public boolean accumulateDistinct(int aggregateId, int groupId, long valueId) {
			return distinctValues.computeIfAbsent(distinctKey(aggregateId, groupId), ignored -> new HashSet<>())
					.add(valueId);
		}
	}

	private static final class Adjacency implements NativeAdjacency {
		final long[] roots;
		final long[][] neighbors;
		final long[][] contexts;
		final int[] payloadReads;

		Adjacency(long[] roots, long[][] neighbors, long[][] contexts) {
			this.roots = roots;
			this.neighbors = neighbors;
			this.contexts = contexts;
			this.payloadReads = new int[roots.length];
		}

		@Override
		public long find(long key) {
			int index = Arrays.binarySearch(roots, key);
			return index < 0 ? NOT_FOUND : index + 1L;
		}

		@Override
		public long size(long handle) {
			return neighbors[Math.toIntExact(handle - 1L)].length;
		}

		@Override
		public long neighborAt(long handle, long offset) {
			int index = Math.toIntExact(handle - 1L);
			payloadReads[index]++;
			return neighbors[index][Math.toIntExact(offset)];
		}

		@Override
		public long contextAt(long handle, long offset) {
			return contexts[Math.toIntExact(handle - 1L)][Math.toIntExact(offset)];
		}

		@Override
		public long keyCount() {
			return roots.length;
		}

		@Override
		public long keyAt(long ordinal) {
			return roots[Math.toIntExact(ordinal)];
		}

		@Override
		public KeyRunCursor openKeyRunCursor() {
			return new KeyRunCursor() {
				int index = -1;

				@Override
				public boolean advance() {
					return ++index < roots.length;
				}

				@Override
				public long key() {
					return roots[index];
				}

				@Override
				public long runHandle() {
					return index + 1L;
				}

				@Override
				public long runSize() {
					return neighbors[index].length;
				}

				@Override
				public long neighborAt(long offset) {
					return Adjacency.this.neighborAt(index + 1L, offset);
				}

				@Override
				public long contextAt(long offset) {
					return Adjacency.this.contextAt(index + 1L, offset);
				}

				@Override
				public int copyNeighbors(long offset, int length, long[] target, int targetOffset) {
					int count = Math.min(length, neighbors[index].length - Math.toIntExact(offset));
					payloadReads[index] += count;
					System.arraycopy(neighbors[index], Math.toIntExact(offset), target, targetOffset, count);
					return count;
				}

				@Override
				public int copyContexts(long offset, int length, long[] target, int targetOffset) {
					int count = Math.min(length, contexts[index].length - Math.toIntExact(offset));
					System.arraycopy(contexts[index], Math.toIntExact(offset), target, targetOffset, count);
					return count;
				}
			};
		}

		@Override
		public void close() {
		}
	}
